import Foundation

/// Built-in UI translations. Unknown diagnostics deliberately fall back to English.
/// Column order is fixed and validated by the localization audit and unit tests.
/// User-authored subtitle text and explicitly verbatim text never enter this catalog.
enum LocalizationCatalog {
    private static let languages: [AppLanguage] = [
        .japanese, .korean, .spanish, .french, .german, .italian, .portuguese,
        .russian, .arabic, .hindi, .turkish, .vietnamese, .thai, .indonesian,
        .dutch, .polish, .ukrainian, .swedish, .danish, .finnish, .hebrew
    ]

    static let entries: [String: [String]] = {
        var result: [String: [String]] = [:]
        for row in translations.split(separator: "\n", omittingEmptySubsequences: true) {
            let columns = row.split(separator: "|", omittingEmptySubsequences: false)
                .map { String($0).replacingOccurrences(of: "\\n", with: "\n") }
            precondition(columns.count == languages.count + 1, "Invalid localization columns")
            precondition(result[columns[0]] == nil, "Duplicate localization key")
            result[columns[0]] = Array(columns.dropFirst())
        }
        return result
    }()

    private static let aliases: [String: String] = [
        "Interface language": "Interface Language",
        "Switch interface language": "Interface Language",
        "Switch interface language · English / 简体中文": "Interface Language",
        "Refresh Languages": "Refresh languages",
        "Follow the current sentence": "Follow Current Sentence",
        "Enter or leave full screen": "Toggle Full Screen"
    ]

    private static func exact(_ english: String, for language: AppLanguage) -> String? {
        guard let index = languages.firstIndex(of: language),
              let values = entries[aliases[english] ?? english] else { return nil }
        return values[index]
    }

    static func translation(_ english: String, for language: AppLanguage) -> String? {
        if let value = exact(english, for: language) { return value }
        switch english {
        case "Back 5 seconds · ⌘←": return exact("Back 5 Seconds", for: language).map { $0 + " · ⌘←" }
        case "Forward 5 seconds · ⌘→": return exact("Forward 5 Seconds", for: language).map { $0 + " · ⌘→" }
        case "Play / Pause · Space":
            guard let play = exact("Play", for: language), let pause = exact("Pause", for: language) else { return nil }
            return play + " / " + pause + " · ␣"
        case "%+.1f s": return "%+.1f s"
        case "MAC NATIVE  /  0.5.3": return "macOS  /  0.5.3"
        default: break
        }
        if english.hasSuffix("…"), let value = exact(String(english.dropLast()), for: language) {
            return value + "…"
        }
        if let matched = templateMatch(english), let value = exact(matched.template, for: language) {
            return substitute(value, arguments: matched.arguments)
        }
        return nil
    }

    private struct Template {
        let source: String
        let regex: NSRegularExpression
        let argumentCount: Int

        init(_ source: String, arguments: Int) {
            self.source = source
            self.argumentCount = arguments
            let numericArguments: Set<Int>
            switch source {
            case "Loaded {0} · {1} cues", " ({0} {1})": numericArguments = [1]
            case "Bilingual captions ready · {0} / {1} cues", "Bilingual captions ready · {0} English / {1} Chinese cues": numericArguments = [0, 1]
            case "Exported {0} cues · {1}", "{0} cues",
                 "{0} subtitle tracks available. Choose a language and source for each track.",
                 "YouTube playback failed ({0}).",
                 "Embedded playback is unavailable (error {0}). Check the message shown in the YouTube player.",
                 "Live audio copying failed ({0}).": numericArguments = [0]
            default: numericArguments = []
            }
            var expression = NSRegularExpression.escapedPattern(for: source)
            for index in 0..<arguments {
                expression = expression.replacingOccurrences(
                    of: NSRegularExpression.escapedPattern(for: "{\(index)}"), with: numericArguments.contains(index) ? "(-?[0-9]+)" : "(.*?)")
            }
            self.regex = try! NSRegularExpression(pattern: "\\A" + expression + "\\z", options: [.dotMatchesLineSeparators])
        }
    }

    private static let templates: [Template] = [
        Template("Loaded {0} · {1} cues", arguments: 2),
        Template("The second-track selection ({0}) has no matching available track. The first track is kept.", arguments: 1),
        Template("YouTube returned no captions matching the first-track selection ({0}). Matching captions may be absent, or access may be restricted.", arguments: 1),
        Template("Exported {0} cues · {1}", arguments: 2),
        Template("Bilingual captions ready · {0} / {1} cues", arguments: 2),
        Template("Auto-translated from {0}", arguments: 1),
        Template("{0} subtitle tracks available. Choose a language and source for each track.", arguments: 1),
        Template("Downloading the first subtitle track ({0})…", arguments: 1),
        Template("{0} cues", arguments: 1),
        Template("YouTube playback failed ({0}).", arguments: 1),
        Template("Embedded playback is unavailable (error {0}). Check the message shown in the YouTube player.", arguments: 1),
        Template(".{0} subtitles are not supported. Choose an SRT, VTT, ASS, or SSA file.", arguments: 1),
        Template("This {0} file contains no usable timed text. Check the timestamps and ensure each end time is after its start time.", arguments: 1),
        Template("Bilingual captions ready · {0} English / {1} Chinese cues", arguments: 2),
        Template(" ({0} {1})", arguments: 2),
        Template("Live audio copying failed ({0}).", arguments: 1)
    ]

    private static func templateMatch(_ english: String) -> (template: String, arguments: [String])? {
        for template in templates {
            guard let match = template.regex.firstMatch(in: english, range: NSRange(english.startIndex..., in: english)) else { continue }
            let arguments = (1...template.argumentCount).compactMap { index -> String? in
                guard let range = Range(match.range(at: index), in: english) else { return nil }
                return String(english[range])
            }
            guard arguments.count == template.argumentCount else { continue }
            return (template.source, arguments)
        }
        return nil
    }

    /// Replace in one pass, so filenames that happen to contain {1} are never rewritten.
    private static func substitute(_ template: String, arguments: [String]) -> String {
        let expression = try! NSRegularExpression(pattern: #"\{([0-9]+)\}"#)
        let source = template as NSString
        var result = ""
        var offset = 0
        for match in expression.matches(in: template, range: NSRange(location: 0, length: source.length)) {
            result += source.substring(with: NSRange(location: offset, length: match.range.location - offset))
            let index = Int(source.substring(with: match.range(at: 1)))!
            result += arguments.indices.contains(index) ? arguments[index] : source.substring(with: match.range)
            offset = NSMaxRange(match.range)
        }
        return result + source.substring(from: offset)
    }

    static func traditionalChinese(english: String, chinese: String) -> String {
        if english == chinese { return english }
        // Convert only known UI text. Protect interpolated filenames and technical details.
        if staticEnglish.contains(english) {
            return chinese.applyingTransform(StringTransform(rawValue: "Simplified-Traditional"), reverse: false) ?? chinese
        }
        guard let match = templateMatch(english) else { return chinese }
        var protected = chinese
        var replacements: [(String, String)] = []
        for (index, argument) in match.arguments.enumerated().sorted(by: { $0.element.count > $1.element.count }) where !argument.isEmpty {
            var scalar = 0xF0000 + index
            var marker = String(UnicodeScalar(scalar)!)
            while chinese.contains(marker) || english.contains(marker) || replacements.contains(where: { $0.0 == marker }) {
                scalar += match.arguments.count
                marker = String(UnicodeScalar(scalar)!)
            }
            protected = protected.replacingOccurrences(of: argument, with: marker)
            replacements.append((marker, argument))
        }
        var converted = protected.applyingTransform(StringTransform(rawValue: "Simplified-Traditional"), reverse: false) ?? protected
        for (marker, argument) in replacements { converted = converted.replacingOccurrences(of: marker, with: argument) }
        return converted
    }

    private static let staticEnglish: Set<String> = Set(staticSource.split(separator: "\n").map {
        String($0).replacingOccurrences(of: "\\n", with: "\n")
    })

